import { describe, expect, it } from "vitest";

import type { ChartTheme } from "@/lib/echarts";

import { buildLineOption } from "./LineChart";

const theme: ChartTheme = {
  textColor: "black",
  mutedTextColor: "gray",
  faintTextColor: "silver",
  axisColor: "rule",
  surfaceColor: "white",
  primaryColor: "gold",
  palette: ["gold", "kinpaku", "green", "danger"],
  tokenColors: {
    "--ks-primary": "gold",
    "--ks-kinpaku": "kinpaku",
    "--ks-success": "green",
    "--ks-danger": "danger",
  },
};

function getSeries(option: ReturnType<typeof buildLineOption>) {
  return option.series as Array<Record<string, unknown>>;
}

describe("buildLineOption", () => {
  it("builds labeled line series with resolved colors, area, dots, and grid", () => {
    const option = buildLineOption(
      [
        { label: "Revenue", data: [-2, 4, 8], color: "var(--ks-primary)" },
        { label: "Cost", data: [1, 3, 5] },
      ],
      ["Jan", "Feb", "Mar"],
      { showArea: true, showDots: true, showGrid: true, theme }
    );

    expect(option.xAxis).toEqual(
      expect.objectContaining({
        type: "category",
        data: ["Jan", "Feb", "Mar"],
        axisLabel: expect.objectContaining({ show: true, color: "silver", fontSize: 10 }),
      })
    );
    expect(option.yAxis).toEqual(
      expect.objectContaining({
        type: "value",
        min: -2,
        max: 8,
        splitNumber: 4,
        splitLine: expect.objectContaining({ show: true }),
      })
    );
    expect(getSeries(option)).toEqual([
      expect.objectContaining({
        name: "Revenue",
        type: "line",
        data: [-2, 4, 8],
        symbol: "circle",
        symbolSize: 6,
        lineStyle: { color: "gold", width: 2, join: "round" },
        itemStyle: { color: "gold" },
        areaStyle: { color: "gold", opacity: 0.12 },
      }),
      expect.objectContaining({
        name: "Cost",
        data: [1, 3, 5],
        lineStyle: { color: "kinpaku", width: 2, join: "round" },
        itemStyle: { color: "kinpaku" },
      }),
    ]);
  });

  it("keeps the chart unfilled and hides dots and grid when disabled", () => {
    const option = buildLineOption([{ label: "Series", data: [2, 4], color: "#123456" }], undefined, {
      showArea: false,
      showDots: false,
      showGrid: false,
      theme,
    });

    expect(option.xAxis).toEqual(
      expect.objectContaining({
        data: ["0", "1"],
        axisLabel: expect.objectContaining({ show: false }),
      })
    );
    expect(option.yAxis).toEqual(
      expect.objectContaining({
        splitLine: expect.objectContaining({ show: false }),
      })
    );
    expect(getSeries(option)[0]).toEqual(
      expect.objectContaining({
        symbol: "none",
        areaStyle: undefined,
        itemStyle: { color: "#123456" },
      })
    );
  });
});

"use client";

import type { EChartsOption } from "echarts";
import { LineChart as EChartsLineChart } from "echarts/charts";
import { GridComponent, TooltipComponent } from "echarts/components";
import { use as useECharts } from "echarts/core";

import { EChartsContainer, resolveChartColor, resolveChartTheme, type ChartTheme } from "@/lib/echarts";
import { cn } from "@/lib/utils";

import type { LineChartProps, LineChartSeries } from "./line-chart.types";

// ECharts registration is global and idempotent; keep the chart module set local.
// eslint-disable-next-line react-hooks/rules-of-hooks
useECharts([EChartsLineChart, GridComponent, TooltipComponent]);

const DEFAULT_COLORS = ["var(--ks-primary)", "var(--ks-kinpaku)", "var(--ks-success)", "var(--ks-danger)"];

export function buildLineOption(
  series: LineChartSeries[],
  labels: string[] | undefined,
  options: Pick<LineChartProps, "showArea" | "showDots" | "showGrid"> & { theme: ChartTheme }
): EChartsOption {
  const categories = labels ?? series[0]?.data.map((_, index) => String(index)) ?? [];
  const values = series.flatMap((item) => item.data);
  const palette = DEFAULT_COLORS.map((color) => resolveChartColor(color, options.theme.tokenColors));
  return {
    animation: true,
    grid: { left: 8, right: 8, top: 12, bottom: labels ? 24 : 12, containLabel: Boolean(labels) },
    xAxis: {
      type: "category",
      data: categories,
      axisLine: { lineStyle: { color: options.theme.axisColor } },
      axisTick: { show: false },
      axisLabel: { show: Boolean(labels), color: options.theme.faintTextColor, fontSize: 10 },
    },
    yAxis: {
      type: "value",
      min: Math.min(...values, 0),
      max: Math.max(...values, 1),
      splitNumber: 4,
      axisLabel: { color: options.theme.faintTextColor, fontSize: 10 },
      splitLine: { show: options.showGrid, lineStyle: { color: options.theme.axisColor } },
      axisLine: { show: false },
    },
    tooltip: { trigger: "axis" },
    series: series.map((item, index) => {
      const color = resolveChartColor(item.color ?? palette[index % palette.length], options.theme.tokenColors);
      return {
        name: item.label,
        type: "line",
        data: item.data,
        symbol: options.showDots ? "circle" : "none",
        symbolSize: options.showDots ? 6 : 0,
        showSymbol: options.showDots,
        lineStyle: { color, width: 2, join: "round" },
        itemStyle: { color },
        areaStyle: options.showArea ? { color, opacity: 0.12 } : undefined,
      };
    }),
  };
}

export function LineChart({
  series,
  labels,
  height = 200,
  width = "100%",
  showArea = true,
  showDots = true,
  showGrid = true,
  showLegend = true,
  className,
  style,
}: LineChartProps) {
  const option = buildLineOption(series, labels, { showArea, showDots, showGrid, theme: resolveChartTheme() });
  return (
    <div className={cn(className)} style={{ ...style, width }}>
      <EChartsContainer
        option={option}
        height={height}
        ariaLabel={`Line chart: ${series.map((item) => item.label).join(", ")}`}
      />
      {showLegend && series.length > 1 && (
        <div className="flex flex-wrap gap-x-(--spacing-lg) gap-y-(--spacing-2xs) mt-(--spacing-sm) px-(--spacing-2xs)">
          {series.map((item, index) => (
            <div key={item.label} className="flex items-center gap-(--spacing-xs)">
              <div
                suppressHydrationWarning
                className="w-6 h-[2px] rounded-full"
                style={{ background: item.color ?? DEFAULT_COLORS[index % DEFAULT_COLORS.length] }}
              />
              <span className="text-body-caption text-muted">{item.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
